handler.function:
const lastMessage = state.messages[state.messages.length - 1];
let userContent = '';

// Extract user input from message
if (lastMessage) {
  if (lastMessage.content) {
    userContent = lastMessage.content;
  } else if (lastMessage.parts && Array.isArray(lastMessage.parts)) {
    userContent = lastMessage.parts[0]?.text || lastMessage.parts[0]?.content || '';
  } else if (typeof lastMessage === 'string') {
    userContent = lastMessage;
  }
}

console.log('📝 Task creation request:', userContent);

// Extract company name
const companyNameMatch = userContent.match(/([^\\s]+)の会社概要|([^\\s]+)の製品|([^\\s]+)の強み|([^\\s]+)を調査/);
const companyName = companyNameMatch ? (companyNameMatch[1] || companyNameMatch[2] || companyNameMatch[3] || companyNameMatch[4]) : null;

if (companyName) {
  console.log('🏢 Detected company name:', companyName);
}

// Create LLM prompt
const taskPrompt = `Please create a detailed task list for the following research request:

${userContent}

🚨 【MUST FOLLOW】🚨
${companyName ? `- The target company for this research is "${companyName}"\n- Use the name "${companyName}" in all tasks\n- Changing "${companyName}" to a different company name is strictly forbidden` : '- Use company and organization names specified by the user exactly as provided'}
- Do not infer or replace company names with different names

Create each task in the following JSON format:
{
  "id": Task ID (numeric),
  "objective": "Task objective",
  "methodology": "Research methodology",
  "deliverables": "Deliverables",
  "success_criteria": "Success criteria",
  "estimated_effort": "Estimated effort (e.g., 2 hours)",
  "dependencies": "Dependent tasks (e.g., Task 1, 2)"
}

You must return your response in the following format:
TASK_LIST_START
[JSON task array]
TASK_LIST_END

Also calculate the total number of tasks and total estimated time.`;

// LLM invocation
const response = await model.invoke([
  { role: 'user', content: taskPrompt }
]);

const content = response.content || '';
console.log('🤖 LLM response received:', content.substring(0, 200));

// Extract task list
const taskListMatch = content.match(/TASK_LIST_START\s*([\s\S]*?)\s*TASK_LIST_END/);
let taskList = [];

if (taskListMatch) {
  try {
    taskList = JSON.parse(taskListMatch[1].trim());
    console.log('✅ Task list parsed successfully:', taskList.length, 'tasks');
  } catch (e) {
    console.error('❌ Task list parsing error:', e);
    // Fallback task
    taskList = [
      {
        id: 1,
        objective: userContent,
        methodology: 'Information gathering and analysis',
        deliverables: 'Research report',
        success_criteria: 'Comprehensive information gathering',
        estimated_effort: '3 hours',
        dependencies: 'None'
      }
    ];
  }
} else {
  console.warn('⚠️  TASK_LIST markers not found, using fallback');
  taskList = [
    {
      id: 1,
      objective: userContent,
      methodology: 'Information gathering and analysis',
      deliverables: 'Research report',
      success_criteria: 'Comprehensive information gathering',
      estimated_effort: '3 hours',
      dependencies: 'None'
    }
  ];
}

// Calculate total time
const totalHours = taskList.reduce((sum, task) => {
  const hours = parseInt((task.estimated_effort || '0時間').replace(/[^\d]/g, '')) || 0;
  return sum + hours;
}, 0);

// Build response
const result = {
  result: {
    taskList: taskList,
    totalTasks: taskList.length,
    totalEstimatedHours: totalHours
  }
};

console.log('📊 Task list completed:', result.result.totalTasks, 'tasks,', result.result.totalEstimatedHours, 'hours');

return {
  messages: [
    {
      role: 'assistant',
      content: JSON.stringify(result, null, 2)
    }
  ],
  taskList: taskList
};
